/// `sessionFileName`: `id.replace(/[^A-Za-z0-9._-]/g, '_') + '.md'` — per
/// UTF-16 unit, so a supplementary character becomes two underscores.
#[must_use]
pub fn session_file_name(id: &str) -> String {
    let mut name = String::with_capacity(id.len() + 3);
    for unit in id.encode_utf16() {
        match char::from_u32(u32::from(unit)) {
            Some(c) if c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-') => name.push(c),
            _ => name.push('_'),
        }
    }
    name.push_str(".md");
    name
}

/// Atomic replace, skipped when the bytes on disk already match (speed-2 T3).
fn write_if_changed(path: &Path, content: &str) -> io::Result<()> {
    if let Ok(existing) = fs::read(path)
        && existing == content.as_bytes()
    {
        return Ok(());
    }
    write_file_atomic(path, content.as_bytes())
}

/// `regenerateProjections`: plan.md, decisions.md, memory.md (only once
/// something is promoted) and sessions/<id>.md per known session.
pub fn regenerate_projections(initiative_dir: &Path, state: &InitiativeState) -> io::Result<()> {
    fs::create_dir_all(initiative_dir)?;
    write_if_changed(&initiative_dir.join("plan.md"), &render_plan(state))?;
    write_if_changed(&initiative_dir.join("decisions.md"), &render_decisions(state))?;
    if !state.memories.is_empty() {
        write_if_changed(&initiative_dir.join("memory.md"), &render_memory(state))?;
    }
    if !state.sessions.is_empty() {
        let sessions_dir = initiative_dir.join("sessions");
        fs::create_dir_all(&sessions_dir)?;
        for session in &state.sessions {
            write_if_changed(
                &sessions_dir.join(session_file_name(&session.id)),
                &render_session(state, session),
            )?;
        }
    }
    Ok(())
}

