                "x".repeat(100)
            ));
        }
        text.push_str("{\"ts\":\"2026-01-02T00:00:00.000Z\",\"type\":\"initiative_status_changed\"}\n");
        text.push_str("{\"ts\":\"2026-01-01T00:00:00.000Z\"}\n");
        std::fs::write(&log, &text).unwrap();
        let newest = newest_event(&log).unwrap();
        assert_eq!(newest.ts, js_date_parse("2026-01-02T00:00:00.000Z").unwrap());
        assert_eq!(newest.event_type.as_deref(), Some("initiative_status_changed"));
        std::fs::write(&log, "").unwrap();
        assert_eq!(newest_event(&log), None);
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
